theorem trdeg_genericZeroField_fin_le {n : ℕ}
    (I : Ideal (MvPolynomial (Fin n) P)) [I.IsPrime] :
    Algebra.trdeg P (GenericZeroField I) ≤ (n : Cardinal)

theorem trdeg_genericZeroField_fin_lt_of_ne_bot {n : ℕ}
    (I : Ideal (MvPolynomial (Fin n) P)) [I.IsPrime] (hI : I ≠ ⊥) :
    Algebra.trdeg P (GenericZeroField I) < (n : Cardinal)

theorem aeval_genericZero_fin_eq_zero_iff_mem {n : ℕ}
    (I : Ideal (MvPolynomial (Fin n) P)) [I.IsPrime] (f : MvPolynomial (Fin n) P) :
    MvPolynomial.aeval (genericZero I) f = 0 ↔ f ∈ I

@[simp]
theorem coefficientModule_monomial (n : ℕ) (r : R) :
    coefficientModule (A := A) (monomial n r) = Submodule.span A {r}

@[simp]
theorem coefficientModule_C (r : R) :
    coefficientModule (A := A) (C r) = Submodule.span A {r}

theorem coefficientModule_mul_C_eq (f : R[X]) (b : R) :
    coefficientModule (A := A) (f * C b) =
      coefficientModule (A := A) f * Submodule.span A {b}

theorem exponent_le_of_mem_support {p : MvPolynomial (Fin n) R}
    (hdegree : p.totalDegree ≤ d) {e : Fin n →₀ ℕ}
    (he : e ∈ p.support) (i : Fin n) :
    e i ≤ d

theorem contentIdeal_le_erase_sup_span (g : R[X]) (m : ℕ) :
    g.contentIdeal ≤
      (g.erase m).contentIdeal ⊔ Ideal.span {g.coeff m}

theorem irreducible_isPrimary
    {R : Type*} [CommRing R] [IsNoetherianRing R] {I : Ideal R}
    (hI : InfIrred I) : I.IsPrimary

theorem nonzeroScalarSaturation_isLeast (M : Submodule R E) :
    IsLeast {G : Submodule R E | M ≤ G ∧ IsGroundModule G}
      (nonzeroScalarSaturation M)
